/**
 * Validate a port value, returning it as an integer. Throws with a descriptive error when the value
 * is not an integer between 1 and 65535.
 *
 * Strings are only accepted when they are a plain integer literal — placeholder values such as
 * `$PORT` are deliberately treated as invalid rather than interpolated, and empty or
 * whitespace-only strings are rejected.
 */
function validatePort(value: string | number): number {
  const received = typeof value === 'string' ? `"${value}"` : `${value}`;
  const fail = (): never => {
    throw new Error(
      `${PORT_ERROR_PREFIX}: Port must be a valid number from 1 to 65535, received ${received}.`
    );
  };

  let port: number;
  if (typeof value === 'number') {
    port = value;
  } else {
    const trimmed = value.trim();
    if (trimmed === '' || !/^\d+$/.test(trimmed)) {
      fail();
    }
    port = Number.parseInt(trimmed, 10);
  }

  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    fail();
  }

  return port;
}

/** Pick the first defined candidate from a priority-ordered list. */
function firstDefined(candidates: Array<string | number | undefined>): string | number | undefined {
  return candidates.find((candidate) => candidate !== undefined);
}

