export function resolveDevCommandOptions<T extends Record<string, any>>(
  cliOptions: T,
  options: ResolveDevCommandContext = {}
): T {
  const env = options.env ?? {};
  const resolved: T = { ...cliOptions };
  const claudePreview = isClaudePreviewLaunch(env);

  // Truthy environment values override the corresponding CLI options.
  if (env.CI) {
    resolved.ci = env.CI as T[keyof T];
